CREATE OR ALTER PROCEDURE dbo.SP_INICIAR_EVALUACION  (        @EvaluacionId INT      , @Usuario      VARCHAR(100)  )  AS  BEGIN        SET NOCOUNT ON;      SET XACT_ABORT ON;          DECLARE            @LoteId                     INT          , @CodigoLote                 VARCHAR(20)          , @EstadoEvaluacionActual     VARCHAR(20)          , @EstadoLoteActual           VARCHAR(20)          , @UsuarioEvaluadorActual     VARCHAR(100)            , @VersionFaseId              INT          , @EvaluacionPadreId          INT            , @VersionFaseOrden           INT          , @CodigoReferencia           VARCHAR(30)          , @FaseCodigo                 VARCHAR(20)          , @EsFinal                    BIT            , @EstadoEnProcesoId          INT          , @EstadoLoteEvaluacionId     INT;          BEGIN TRY            BEGIN TRANSACTION;              /* =========================================================             1. OBTENER EVALUACION + LOTE + ETAPA             ========================================================= */            SELECT                @LoteId =                    E.LoteId                , @CodigoLote =                    L.CodigoLote                , @EstadoEvaluacionActual =                    EE.Codigo                , @EstadoLoteActual =                    EL.Codigo                , @UsuarioEvaluadorActual =                    E.UsuarioEvaluador                , @VersionFaseId =                    E.VersionFaseId                , @EvaluacionPadreId =                    E.EvaluacionPadreId                , @VersionFaseOrden =                    VF.Orden                , @CodigoReferencia =                    VF.CodigoReferencia                , @FaseCodigo =                    F.Codigo                , @EsFinal =                    VF.EsFinal            FROM dbo.EVALUACION E WITH (UPDLOCK, HOLDLOCK)            INNER JOIN dbo.ESTADO_EVALUACION EE              ON EE.EstadoEvaluacionId =                 E.EstadoEvaluacionId            INNER JOIN dbo.LOTE L WITH (UPDLOCK, HOLDLOCK)              ON L.LoteId =                 E.LoteId            INNER JOIN dbo.ESTADO_LOTE EL              ON EL.EstadoLoteId =                 L.EstadoLoteId            LEFT JOIN dbo.VERSIONFASE VF              ON VF.VersionFaseId =                 E.VersionFaseId            LEFT JOIN dbo.FASE F              ON F.FaseId =                 VF.FaseId            WHERE E.EvaluacionId =                @EvaluacionId              AND E.Estado =                'ACTIVO'              AND L.Estado =                'ACTIVO';              /* =========================================================             2. VALIDAR EXISTENCIA             ========================================================= */            IF @LoteId IS NULL          BEGIN                RAISERROR(                  'La evaluación no existe, está inactiva o pertenece a un lote inactivo.',                  16,                  1              );            END;              /* =========================================================             3. VALIDAR ESTADO ACTUAL DE LA EVALUACION             ========================================================= */            IF @EstadoEvaluacionActual <> 'PENDIENTE'          BEGIN                RAISERROR(                  'Solo se puede iniciar una evaluación en estado PENDIENTE.',                  16,                  1              );            END;              /* =========================================================             4. VALIDAR QUE NO HAYA SIDO ASIGNADA             ========================================================= */            IF @UsuarioEvaluadorActual IS NOT NULL             AND LTRIM(RTRIM(@UsuarioEvaluadorActual)) <> ''          BEGIN                RAISERROR(                  'La evaluación ya se encuentra asignada a un evaluador.',                  16,                  1              );            END;              /* =========================================================             5. VALIDAR ESTADO DEL LOTE               NUEVO MOTOR POR ETAPAS:               PENDIENTE               -> Primera evaluación del lote.               EVALUACION               -> Siguiente etapa.               -> Reevaluación de una etapa.               NO se permite iniciar desde:               LIBERADO               NO_CONFORME               CERTIFICADO               ANULADO               u otro estado.             ========================================================= */            IF @EstadoLoteActual NOT IN          (              'PENDIENTE',              'EVALUACION'          )          BEGIN                RAISERROR(                  'Solo se puede iniciar una evaluación cuando el lote está PENDIENTE o EVALUACION.',                  16,                  1              );            END;              /* =========================================================             6. VALIDAR ETAPA DE LA EVALUACION               Para evaluaciones nuevas con VERSIONFASE:               - La etapa debe existir.             - Debe estar activa.               VersionFaseId NULL se conserva únicamente para             evaluaciones históricas / legacy.             ========================================================= */            IF @VersionFaseId IS NOT NULL          BEGIN                IF NOT EXISTS              (                  SELECT 1                    FROM dbo.VERSIONFASE VF                    WHERE VF.VersionFaseId =                        @VersionFaseId                      AND VF.Estado = 1              )              BEGIN                    RAISERROR(                      'La etapa asociada a la evaluación no existe o se encuentra inactiva.',                      16,                      1                  );                END;            END;              /* =========================================================             7. VALIDAR REEVALUACION               Si existe EvaluacionPadreId:               - El padre debe existir.             - Debe pertenecer al mismo lote.             - Debe corresponder a la misma etapa.             - Debe haber terminado NO CONFORME.               ResultadoGeneral = 0 identifica que el intento padre             terminó con incumplimiento.             ========================================================= */            IF @EvaluacionPadreId IS NOT NULL          BEGIN                IF NOT EXISTS              (                  SELECT 1                    FROM dbo.EVALUACION EP                    INNER JOIN dbo.ESTADO_EVALUACION EEP                      ON EEP.EstadoEvaluacionId =                         EP.EstadoEvaluacionId                    WHERE EP.EvaluacionId =                        @EvaluacionPadreId                      AND EP.LoteId =                        @LoteId                      AND EP.Estado =                        'ACTIVO'                      AND EEP.Codigo =                        'TERMINADA'                      AND EP.ResultadoGeneral = 0                      AND                    (                        (                            @VersionFaseId IS NULL                            AND EP.VersionFaseId IS NULL                        )                          OR EP.VersionFaseId =                           @VersionFaseId                    )              )              BEGIN                    RAISERROR(                      'La evaluación padre no es válida para esta reevaluación.',                      16,                      1                  );                END;            END;              /* =========================================================             8. OBTENER ESTADO EN_PROCESO DE EVALUACION             ========================================================= */            SELECT              @EstadoEnProcesoId =                  EstadoEvaluacionId            FROM dbo.ESTADO_EVALUACION            WHERE Codigo =                'EN_PROCESO';              IF @EstadoEnProcesoId IS NULL          BEGIN                RAISERROR(                  'No existe el estado de evaluación EN_PROCESO.',                  16,                  1              );            END;              /* =========================================================             9. OBTENER ESTADO EVALUACION DEL LOTE             ========================================================= */            SELECT              @EstadoLoteEvaluacionId =                  EstadoLoteId            FROM dbo.ESTADO_LOTE            WHERE Codigo =                'EVALUACION';              IF @EstadoLoteEvaluacionId IS NULL          BEGIN                RAISERROR(                  'No existe el estado de lote EVALUACION.',                  16,                  1              );            END;              /* =========================================================             10. TOMAR / INICIAR EVALUACION               Se conserva protección de concurrencia:               solamente una evaluación todavía PENDIENTE y sin             evaluador puede ser tomada.             ========================================================= */            UPDATE dbo.EVALUACION            SET                EstadoEvaluacionId =                    @EstadoEnProcesoId                , UsuarioEvaluador =                    @Usuario                , FechaInicio =                    SYSDATETIME()                , AudUsuarioModificacion =                    @Usuario                , AudFechaActualizacion =                    SYSDATETIME()            WHERE EvaluacionId =                @EvaluacionId              AND Estado =                'ACTIVO'              AND EstadoEvaluacionId =            (                SELECT EstadoEvaluacionId                  FROM dbo.ESTADO_EVALUACION                  WHERE Codigo =                      'PENDIENTE'            )              AND            (                UsuarioEvaluador IS NULL                OR LTRIM(RTRIM(UsuarioEvaluador)) = ''            );              IF @@ROWCOUNT = 0          BEGIN                RAISERROR(                  'No fue posible iniciar la evaluación. Puede haber sido tomada por otro evaluador.',                  16,                  1              );            END;              /* =========================================================             11. ACTUALIZAR ESTADO DEL LOTE               Primera etapa:                 PENDIENTE -> EVALUACION               Siguientes etapas / reevaluaciones:                 EVALUACION -> EVALUACION             ========================================================= */            UPDATE dbo.LOTE            SET                EstadoLoteId =                    @EstadoLoteEvaluacionId                , AudUsuarioModificacion =                    @Usuario                , AudFechaActualizacion =                    GETDATE()            WHERE LoteId =                @LoteId              AND Estado =                'ACTIVO';              IF @@ROWCOUNT = 0          BEGIN                RAISERROR(                  'No fue posible actualizar el estado del lote.',                  16,                  1              );            END;              /* =========================================================             12. CONFIRMAR TRANSACCION             ========================================================= */            COMMIT TRANSACTION;              /* =========================================================             13. RESULTADO             ========================================================= */            SELECT                0 AS CodigoResultado                , CASE                    WHEN @EvaluacionPadreId IS NOT NULL                        THEN 'Reevaluación iniciada correctamente.'                      WHEN @EstadoLoteActual = 'PENDIENTE'                        THEN 'Evaluación inicial iniciada correctamente.'                      ELSE                        'Evaluación de la siguiente etapa iniciada correctamente.'                END AS Mensaje                , @EvaluacionId                  AS EvaluacionId                , @LoteId                  AS LoteId                , @CodigoLote                  AS CodigoLote                , @Usuario                  AS UsuarioEvaluador                , @VersionFaseId                  AS VersionFaseId                , @VersionFaseOrden                  AS VersionFaseOrden                , @CodigoReferencia                  AS CodigoReferencia                , @FaseCodigo                  AS FaseCodigo                , @EsFinal                  AS EsFinal                , @EvaluacionPadreId                  AS EvaluacionPadreId                , CASE                    WHEN @EvaluacionPadreId IS NOT NULL                        THEN CAST(1 AS BIT)                    ELSE CAST(0 AS BIT)                END AS EsReevaluacion                , 'EN_PROCESO'                  AS EstadoEvaluacion                , 'EVALUACION'                  AS EstadoLote;          END TRY        BEGIN CATCH            IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION;              SELECT                -1 AS CodigoResultado              , ERROR_NUMBER() AS ErrorNumero              , ERROR_LINE() AS ErrorLinea              , ERROR_PROCEDURE() AS ErrorProcedimiento              , ERROR_MESSAGE() AS Mensaje;        END CATCH;    END;
GO
